export function Mention({
  fullName = "{{fullName}}",
  handle = "{{handle}}",
  style = "{{style}}",
  isCurrentUser = {{isCurrentUser}},
  accent = "{{accent}}",
}) {
  const wrap = style === "pill"
    ? { background: accent, padding: "2px 10px", borderRadius: 999 }
    : { borderBottom: `2px solid ${accent}`, paddingBottom: 1 };
  return (
    <span style={{ display: "inline-flex", alignItems: "baseline", gap: 4, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", ...wrap }}>
      <span style={{ fontWeight: 600, textDecoration: isCurrentUser ? "underline" : "none" }}>{fullName}</span>
      <span style={{ fontSize: 12, color: "#24143080" }} aria-hidden="true">@{handle}</span>
      {isCurrentUser && <span style={{ fontSize: 12, color: "#24143080", fontStyle: "italic" }}>(you)</span>}
    </span>
  );
}
